def bridgePath (y T z : ℝ) (g : BridgeNoise) : C(BridgeTime, ℝ) :=
  ⟨fun t => (1 - (t : ℝ)) * y + (t : ℝ) * z + Real.sqrt T * g.val t,
    by fun_prop⟩

def pinPath (f : C(BridgeTime, ℝ)) : BridgeNoise :=
  ⟨f - f 0 • leftWeight - f 1 • rightWeight,
    by constructor <;> simp [leftWeight, rightWeight]⟩

def sourceIntervalCompletion (ν : Measure BridgeNoise) (a y T z : ℝ) : ℝ :=
  if 0 < T then intervalCompletion ν a y T z
  else if T = 0 ∧ y = z ∧ |y| < a then 1 else 0

def remainingEnergy {n : ℕ} (a : Shao.Path n) (r : ℕ)
    (σ : LabelPerm n) : ℝ :=
  Shao.energy a - Shao.prefixSquares (Spitzer.reorder a σ) r

def revealLaw {n : ℕ} (P : Measure (Shao.Path n)) :
    Measure (Shao.Path n × LabelPerm n) :=
  P.prod (uniformPermutationLaw n)

def retainedSum {n : ℕ} (J : MonitoredDomain) (F G : BridgeKernel)
    (a : Shao.Path n) (x : ℝ) (ν : LabelPerm n → ℕ) (σ : LabelPerm n) : ℝ :=
  ∑ r ∈ Finset.range n, sourceRetainedRemainder J F G a x ν r σ

def separatedSum {n : ℕ} (J : MonitoredDomain) (G : BridgeKernel)
    (a : Shao.Path n) (x : ℝ) (ν : LabelPerm n → ℕ) (σ : LabelPerm n) : ℝ :=
  ∑ r ∈ Finset.range n, sourceSeparatedOvershoot J G a x ν r σ
